import { test } from "node:test";
import assert from "node:assert/strict";
import { WORLD_FACTS } from "./course-facts";
import { WORLD_NOTES } from "./course-notes";
import { CABINET_NOTES } from "./cabinet-notes";
import { BUILT_IN_WORLDS } from "@/lib/built-in-worlds";
import { byKind } from "./registry";
import { isHazard } from "@/lib/worlddoc";

/**
 * The cache invalidator for `course-facts.ts`.
 *
 * That file is generated by `npm run courses:stats` and read by every guide
 * page as though it were true. It is a cache of a measurement, and a cache
 * with no invalidator goes stale silently — which on these pages means
 * publishing a specific number about a course that no longer has that shape.
 * Wrong specifics are worse than no specifics, because a reader can check
 * them.
 *
 * The cheap half of the measurement is re-run here: part counts, hazard
 * counts, checkpoints and the bounding box, all of which are a pass over the
 * document. The route figures are a Dijkstra per course and are deliberately
 * NOT recomputed — `medals.test.ts` already pays that cost for the same
 * geometry, and a course whose block count is unchanged has not moved.
 */
test("the generated world facts still describe the worlds", () => {
  for (const world of BUILT_IN_WORLDS) {
    const doc = world.build("user-1");
    const facts = WORLD_FACTS[world.slug];
    assert.ok(
      facts,
      `${world.slug} has no row in course-facts.ts. Run \`npm run courses:stats\`.`
    );

    const xs = doc.parts.map((p) => p[0]);
    const ys = doc.parts.map((p) => p[1]);
    const zs = doc.parts.map((p) => p[2]);
    const actual = {
      parts: doc.parts.length,
      props: doc.props.length,
      checkpoints: doc.checkpoints?.length ?? 0,
      hazards: doc.parts.filter(isHazard).length,
      spanX: Math.max(...xs) - Math.min(...xs) + 1,
      spanZ: Math.max(...zs) - Math.min(...zs) + 1,
      spanY: Math.max(...ys) - Math.min(...ys) + 1,
    };

    for (const [key, value] of Object.entries(actual)) {
      assert.equal(
        facts[key as keyof typeof actual],
        value,
        `${world.slug}.${key} is ${facts[key as keyof typeof actual]} in ` +
          `course-facts.ts but ${value} in the world the game builds. ` +
          `Run \`npm run courses:stats\`.`
      );
    }

    // A course has a goal and therefore a route; a sandbox has neither. A row
    // with the wrong one of those is a guide page that either promises medal
    // times it has none of or omits the only interesting numbers it has.
    assert.equal(
      Boolean(facts.route),
      Boolean(doc.goal),
      `${world.slug}: course-facts.ts ${facts.route ? "has" : "has no"} route ` +
        `but the world ${doc.goal ? "has" : "has no"} goal.`
    );
  }
});

/**
 * A guide page with no words on it is the thing this whole exercise is about
 * not shipping. There is no way to assert that prose is good; there is a way
 * to assert that it exists and is not a stub, and that is worth having
 * because the failure mode is adding a course and forgetting the notes.
 */
test("every guidable thing has notes written for it", () => {
  for (const world of BUILT_IN_WORLDS) {
    const notes = WORLD_NOTES[world.slug];
    assert.ok(notes, `${world.slug} has no entry in course-notes.ts.`);
    assert.ok(
      notes.what.length > 120 && notes.route.length > 120,
      `${world.slug}'s notes are too short to be worth a page.`
    );
    // Only a course can be approached — a world with no goal has no run to
    // plan, and inventing one would be the filler these pages exist to avoid.
    assert.equal(
      Boolean(notes.approach),
      Boolean(world.build("user-1").goal),
      `${world.slug}: an approach is for a course, not a sandbox.`
    );
  }

  for (const cabinet of byKind("arcade")) {
    const notes = CABINET_NOTES[cabinet.slug];
    assert.ok(notes, `${cabinet.slug} has no entry in cabinet-notes.ts.`);
    assert.ok(
      notes.what.length > 120 && notes.scoring.length > 80,
      `${cabinet.slug}'s notes are too short to be worth a page.`
    );
  }
});
